<?php require_once __DIR__.'/functions.php';require_login();header('Content-Type: application/json; charset=utf-8');if($_SERVER['REQUEST_METHOD']!=='POST')exit;verify_csrf();try{$action=$_POST['action']??'';$db=load_db();$words=&$db['words'];if($action==='save_word'){$word=sanitize_word(json_decode($_POST['word']??'{}',true)?:[]);if(!$word['hanzi']||!$word['pinyin'])throw new RuntimeException('Hanzi and Pinyin required');if($word['id']<=0)$word['id']=max(array_map(fn($w)=>(int)($w['id']??0),$words?:[['id'=>0]]))+1;$i=find_word_index($words,$word['id']);if($i>=0)$words[$i]=$word;else $words[]=$word;save_db($db);echo json_encode(['ok'=>true,'word'=>$word]);}elseif($action==='delete'){$ids=array_map('strval',json_decode($_POST['ids']??'[]',true)?:[]);$db['words']=array_values(array_filter($words,fn($w)=>!in_array((string)$w['id'],$ids,true)));save_db($db);echo json_encode(['ok'=>true]);}elseif($action==='bulk'){$ids=array_map('strval',json_decode($_POST['ids']??'[]',true)?:[]);foreach($words as &$w)if(in_array((string)$w['id'],$ids,true)){if(($_POST['level']??'')!=='')$w['level']=$_POST['level']==='Extra'?'Extra':(int)$_POST['level'];if(trim($_POST['category']??'')!=='')$w['category']=trim($_POST['category']);}save_db($db);echo json_encode(['ok'=>true]);}elseif($action==='upload_audio'){$id=$_POST['id']??'';$ext=strtolower(pathinfo($_FILES['audio']['name']??'',PATHINFO_EXTENSION));if(empty($_FILES['audio']['tmp_name'])||!in_array($ext,ALLOWED_AUDIO_EXT,true)||$_FILES['audio']['size']>MAX_AUDIO_SIZE)throw new RuntimeException('Invalid audio');if(!is_dir(AUDIO_DIR))mkdir(AUDIO_DIR,0755,true);$name=preg_replace('/[^\pL\pN_.-]+/u','_',pathinfo($_FILES['audio']['name'],PATHINFO_FILENAME)).'-'.time().'.'.$ext;move_uploaded_file($_FILES['audio']['tmp_name'],AUDIO_DIR.'/'.$name);$rel='audio/'.$name;$i=find_word_index($words,$id);if($i>=0){$words[$i]['audio']=$rel;save_db($db);}echo json_encode(['ok'=>true,'audio'=>$rel]);}else throw new RuntimeException('Unknown action');}catch(Throwable $e){http_response_code(400);echo json_encode(['ok'=>false,'error'=>$e->getMessage()]);}?>